from textsx import X
P="AR-Y7-NN-"
X(P+"T1-L01","إجازتي في الجبال","قضيتُ إجازتي مع أسرتي في جبال حتّا.|كانت الرحلة ممتعة والجوّ لطيفًا.|زرتُ السدّ وركبتُ قاربًا صغيرًا.|تعلّمتُ أسماء بعض الطيور والنباتات.|أريد أن أعود إلى هناك في الإجازة القادمة.","قضى الكاتب إجازته في جبال حتّا+|كان الجوّ حارًّا جدًّا-|ركب الكاتب قاربًا+","أين قضى الكاتب إجازته؟ في جبال حتّا مع أسرته.|ماذا تعلّم؟ أسماء بعض الطيور والنباتات.")
X(P+"T1-L02","يوم المساعدة","في يوم السبت أساعد أمّي في البيت.|أرتّب غرفتي وأغسل الصحون.|أختي تساعد أمّي في الطبخ.|نقسم المهامّ بيننا، فننتهي بسرعة.|المساعدة في البيت مسؤولية كل فرد في الأسرة.","يساعد الكاتب أمّه يوم السبت+|الأخت تغسل الصحون-|المساعدة مسؤولية الجميع+","ماذا يفعل الكاتب في البيت؟ يرتّب غرفته ويغسل الصحون.|لماذا ينتهون بسرعة؟ لأنهم يقسمون المهامّ بينهم.")
X(P+"T1-L03","مشروع ليلى","عند ليلى فكرة: أن تبيع كعكًا صحّيًّا في سوق المدرسة.|حسبت التكلفة: خمسون درهمًا للمواد.|صمّمت إعلانًا صغيرًا ونشرته في المدرسة.|جاء زبائن كثيرون، وكان الربح مئة درهم.|تعلّمت ليلى أنّ المشروع الصغير يحتاج إلى تخطيط.","فكرة ليلى بيع الحلوى-|تكلفة المواد خمسون درهمًا+|كان ربح ليلى مئة درهم+","ماذا تبيع ليلى؟ كعكًا صحّيًّا.|ماذا تعلّمت ليلى؟ أنّ المشروع الصغير يحتاج إلى تخطيط.")
X(P+"T1-L04","حملة تنظيف الشاطئ","شاركتُ في حملة تطوّعية لتنظيف الشاطئ.|كان معنا متطوّعون من أعمار مختلفة.|جمعنا أكياسًا كثيرة من البلاستيك.|ثمّ زرنا دار المسنّين وقرأنا لهم القصص.|العمل الخيري يجعلني سعيدًا ويخدم مجتمعي.","نظّف المتطوّعون الحديقة-|جمعوا البلاستيك من الشاطئ+|زاروا دار المسنّين+","ماذا جمع المتطوّعون؟ أكياسًا كثيرة من البلاستيك.|ماذا فعلوا في دار المسنّين؟ قرأوا لهم القصص.")
X(P+"T1-L05","قيمة العمل","العمل يساعد الإنسان على الاعتماد على النفس.|كلّ مهنة مهمّة للمجتمع: الطبيب والمزارع والعامل.|بالعمل يزيد الإنتاج وتتقدّم الدول.|أمّا الكسل فيضيّع الوقت والفرص.|لذلك نحترم كلّ من يعمل بإخلاص.","العمل يساعد على الاعتماد على النفس+|بعض المهن غير مهمّة-|الكسل يضيّع الفرص+","ماذا يحدث بالعمل؟ يزيد الإنتاج وتتقدّم الدول.|ماذا يضيّع الكسل؟ الوقت والفرص.")
X(P+"T1-L06","هاتفي الجديد","اشترى لي أبي هاتفًا جديدًا في عيد ميلادي.|شاشته كبيرة وبطّاريته قوية.|أحمل الشاحن معي دائمًا في الحقيبة.|أستخدم تطبيقًا لإرسال الرسائل إلى أصدقائي.|لكنّي لا أستخدمه أكثر من ساعتين في اليوم.","اشترى الأب الهاتف في العيد الوطني-|بطّارية الهاتف قوية+|يستخدم الكاتب الهاتف ساعتين فقط+","ماذا يحمل الكاتب في الحقيبة؟ الشاحن.|كم ساعة يستخدم الهاتف؟ ساعتين في اليوم.")
X(P+"T1-L07","أكثر من هاتف","الهاتف اليوم ليس للاتصال فقط.|فيه خريطة تدلّنا على الطريق، ومنبّه يوقظنا.|وفيه آلة حاسبة ومصرف رقمي.|نحجز به تذاكر الطيران ونتعلّم به اللغات.|لذلك نقول: الهاتف أداة لكل شيء تقريبًا.","الهاتف للاتصال فقط-|في الهاتف آلة حاسبة+|نحجز التذاكر بالهاتف+","اذكر شيئين في الهاتف. خريطة ومنبّه (أو آلة حاسبة).|ماذا نتعلّم بالهاتف؟ اللغات.")
X(P+"T1-L08","هاتف المستقبل","كيف سيكون الهاتف بعد عشر سنوات؟|سيكون هاتفًا قابلًا للطيّ مثل الورقة.|وسوف يساعدنا الذكاء الاصطناعي في كل عمل.|سنزور أماكن بعيدة بالواقع الافتراضي.|وربّما يصبح الهاتف ساعة ذكية في اليد فقط.","سيصبح الهاتف أكبر وأثقل-|سيساعدنا الذكاء الاصطناعي+|سنزور أماكن بالواقع الافتراضي+","كيف سيكون شكل الهاتف؟ قابلًا للطيّ مثل الورقة.|ماذا قد يصبح الهاتف؟ ساعة ذكية في اليد.")
X(P+"T1-L09","هاتف أم حاسوب؟","للدراسة أستخدم الحاسوب أكثر من الهاتف.|شاشة الحاسوب أكبر، ولوحة المفاتيح أسهل في الكتابة.|أمّا الهاتف فهو أخفّ وأسهل في الحمل.|الحاسوب أسرع في البرامج الكبيرة.|لكلّ جهاز استخدام مناسب.","الهاتف أخفّ من الحاسوب+|شاشة الهاتف أكبر-|الحاسوب أسرع في البرامج الكبيرة+","لماذا يستخدم الكاتب الحاسوب للدراسة؟ لأنّ شاشته أكبر والكتابة عليه أسهل.|ما ميزة الهاتف؟ خفيف وسهل الحمل.")
X(P+"T1-L10","يوم بلا هاتف","قرّرت أسرتنا أن نعيش يوم الجمعة بلا هاتف.|في البداية شعرنا بالملل.|ثمّ خرجنا إلى الطبيعة ولعبنا ألعابًا جماعية.|تحدّثنا كثيرًا وضحكنا معًا.|كان التواصل المباشر أجمل من الشاشة.","عاشت الأسرة يوم السبت بلا هاتف-|شعروا بالملل في البداية+|لعبوا ألعابًا جماعية+","ماذا شعروا في البداية؟ بالملل.|ماذا كان أجمل من الشاشة؟ التواصل المباشر.")
X(P+"T2-L01","ليلة في المخيّم","في الشتاء خيّمنا في صحراء الإمارات.|نصبنا الخيمة وجمعنا الحطب.|أشعلنا النار وشربنا الشاي.|في الليل نمتُ في كيس النوم.|وقبل النوم رأيتُ النجوم بالمصباح مطفأً.","خيّمت الأسرة في الصيف-|جمعوا الحطب للنار+|نام الكاتب في كيس النوم+","ماذا فعلوا بعد إشعال النار؟ شربوا الشاي.|ماذا رأى الكاتب قبل النوم؟ النجوم.")
X(P+"T2-L02","بيت جدّتي","بيت جدّتي دافئ ومريح.|في غرفة الجلوس نتجمّع كل أسبوع.|يزورنا الجيران ويشربون القهوة معنا.|جدّتي تحكي لنا قصصًا بحنان.|أشعر في بيتها بالأمان والسعادة.","البيت بارد وغير مريح-|يتجمّع الأقارب كل أسبوع+|الجدّة تحكي قصصًا+","أين يتجمّعون؟ في غرفة الجلوس.|بماذا يشعر الكاتب في بيت جدّته؟ بالأمان والسعادة.")
X(P+"T2-L03","يوم تبادلنا الأدوار","في يوم مختلف تبادلتُ الدور مع أمّي.|طبختُ الغداء ورتّبت البيت.|كان العمل صعبًا ومتعبًا.|وأمّي ذهبت إلى المدرسة مكاني لتقرأ قصة للطلاب.|في المساء قلت: «الآن أفهم كم تتعب أمّي!».","تبادل الكاتب الدور مع أبيه-|كان العمل سهلًا-|فهم الكاتب تعب أمّه+","ماذا فعل الكاتب في هذا اليوم؟ طبخ الغداء ورتّب البيت.|ماذا قال في المساء؟ الآن أفهم كم تتعب أمّي.")
X(P+"T2-L04","المخترع والمكتشف","المخترع يصنع شيئًا جديدًا لم يكن موجودًا.|مثل المصباح الكهربائي والهاتف.|أمّا المكتشف فيجد شيئًا موجودًا لم نعرفه.|مثل اكتشاف كوكب جديد أو دواء في نبات.|العالم يحتاج إلى التجربة في الحالتين.","المصباح اختراع+|المكتشف يصنع شيئًا جديدًا-|التجربة مهمّة للعالم+","ما الفرق بين المخترع والمكتشف؟ المخترع يصنع جديدًا والمكتشف يجد موجودًا.|اذكر مثالًا على اكتشاف. كوكب جديد أو دواء في نبات.")
X(P+"T2-L05","بين الأمس واليوم","قديمًا كان الناس يسافرون على الجمال أيامًا.|وكانوا يرسلون الرسائل مع المسافرين.|ثمّ تطوّرت وسائل النقل والاتصال.|اليوم نسافر بالطائرة في ساعات.|ونرسل الرسالة في ثانية واحدة، فالحياة أسهل.","قديمًا سافر الناس بالطائرة-|اليوم نرسل الرسالة في ثانية+|الحياة اليوم أسهل+","كيف كان الناس يسافرون قديمًا؟ على الجمال.|كيف نسافر اليوم؟ بالطائرة.")
X(P+"T2-L06","المخترع الصغير","لاحظ سالم مشكلة: الماء يُهدر في حديقة المدرسة.|فكّر في حلّ، وصمّم نموذجًا لريّ ذكي.|استخدم أدوات بسيطة وحسّاسًا صغيرًا.|يفتح النظام الماء فقط عندما تجفّ التربة.|فاز سالم بالمركز الأول في مسابقة المدرسة.","المشكلة إهدار الكهرباء-|يفتح النظام الماء عند جفاف التربة+|فاز سالم بالمركز الأول+","ما المشكلة التي لاحظها سالم؟ إهدار الماء في حديقة المدرسة.|ماذا صمّم؟ نموذجًا لريّ ذكي.")
X(P+"T3-L01","ضباب الكابتشينو","في الشتاء تحدث ظاهرة نادرة في جبال الإمارات.|يملأ الضباب الوادي فيشبه رغوة القهوة.|لذلك يسمّيها الناس «ظاهرة الكابتشينو».|تحدث بسبب الرطوبة العالية وبرودة الصباح.|الرؤية تقلّ فيها، فيجب الحذر عند القيادة.","تحدث الظاهرة في الصيف-|يشبه الضباب رغوة القهوة+|يجب الحذر عند القيادة+","لماذا تُسمّى ظاهرة الكابتشينو؟ لأنّ الضباب يشبه رغوة القهوة.|ما سببها؟ الرطوبة العالية وبرودة الصباح.")
X(P+"T3-L02","وجوه القمر","القمر يدور حول الأرض كل شهر.|في أول الشهر نراه هلالًا صغيرًا.|وفي منتصف الشهر يصبح بدرًا كاملًا.|يعتمد الشهر القمري على حركة القمر.|وأحيانًا يحدث الخسوف عندما تقع الأرض بين الشمس والقمر.","يدور القمر حول الشمس-|البدر في منتصف الشهر+|يحدث الخسوف عندما تقع الأرض بين الشمس والقمر+","متى نرى الهلال؟ في أول الشهر.|على ماذا يعتمد الشهر القمري؟ على حركة القمر.")
X(P+"T3-L03","شمسنا","الشمس نجم كبير يعطينا الضوء والحرارة.|نرى الشروق في الصباح والغروب في المساء.|في الإمارات نستخدم الطاقة الشمسية لصنع الكهرباء.|وأحيانًا يحدث الكسوف فيغطّي القمر الشمس.|لا ننظر إلى الشمس مباشرة لأنها تضرّ العين.","الشمس كوكب صغير-|نستخدم الطاقة الشمسية لصنع الكهرباء+|النظر إلى الشمس مباشرة يضرّ العين+","ماذا تعطينا الشمس؟ الضوء والحرارة.|ما الكسوف؟ أن يغطّي القمر الشمس.")
X(P+"T3-L04","الأرض تتحرّك","قشرة الأرض ليست ثابتة دائمًا.|عندما تتحرّك يحدث الزلزال.|وأحيانًا يخرج من البركان حمم حارّة.|الزلازل والبراكين خطر على الناس.|لذلك تتدرّب المدارس على خطة الإخلاء.","قشرة الأرض ثابتة دائمًا-|يخرج من البركان حمم حارّة+|تتدرّب المدارس على الإخلاء+","متى يحدث الزلزال؟ عندما تتحرّك قشرة الأرض.|لماذا تتدرّب المدارس؟ لتستعدّ لخطر الزلازل بخطة الإخلاء.")
X(P+"T3-L05","عندما يأتي الإعصار","الإعصار عاصفة قوية جدًّا.|يأتي معه مطر غزير وسيول.|يتابع مركز الأرصاد التوقّعات ويحذّر الناس.|قد يسبّب الإعصار أضرارًا في البيوت والطرق.|نبقى في البيت ونتّبع تعليمات الجهات الرسمية.","الإعصار ريح خفيفة-|مركز الأرصاد يحذّر الناس+|نتّبع التعليمات الرسمية+","ماذا يأتي مع الإعصار؟ مطر غزير وسيول.|ماذا نفعل عند الإعصار؟ نبقى في البيت ونتّبع التعليمات.")
X(P+"T3-L06","كوارث نصنعها نحن","بعض الكوارث من صنع الإنسان.|التلوّث والنفايات تضرّ البحر والهواء.|قطع الأشجار يقلّل الأكسجين.|والتسرّب النفطي يقتل الأسماك والطيور.|نستطيع أن نحمي الأرض بسلوك مسؤول.","كل الكوارث طبيعية-|قطع الأشجار يقلّل الأكسجين+|التسرّب النفطي يضرّ الأسماك+","ماذا يضرّ البحر والهواء؟ التلوّث والنفايات.|كيف نحمي الأرض؟ بسلوك مسؤول.")
